def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70

    supply = day_context['supply']
    day = day_context['day']

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', True):
            alive_opps.append(o)

    if not alive_opps:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # Extract yesterday bids (only immediate trace)
    yesterday_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev['bid']))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Supply pressure: with supply in [15,25], water is scarce; prefer to avoid no-water days.
    # Estimate how many water units are likely to be contested (heuristic).
    # Use int() for safety even though we don't index arrays.
    supply_int = int(supply)
    units_possible = max(0, supply_int // WATER_REQ)

    # Aggression calibration based on yesterday behavior
    high_bid_threshold = DAILY_SALARY * 0.85  # ~59.5
    if highest_prev_bid >= high_bid_threshold:
        # Someone is fighting hard. If I'm healthy, slightly undercut; if low HP, match pressure.
        if my_status['hp'] > 3:
            target = DAILY_SALARY * 0.32
        else:
            target = DAILY_SALARY * 0.88
    else:
        # No strong evidence of extreme bids; bid enough to stay safe.
        if my_status['hp'] <= 2:
            target = DAILY_SALARY * 0.9
        else:
            # If supply is near minimum, increase a bit.
            if supply_int <= int(15):
                target = DAILY_SALARY * 0.62
            else:
                target = DAILY_SALARY * 0.52

    # If I already have consecutive no-water days, ramp up.
    no_water_days = int(my_status.get('no_water_days', 0) or 0)
    if no_water_days >= 2:
        target *= 1.25
    elif no_water_days == 1:
        target *= 1.12

    # Ensure bid is within budget.
    bid = min(my_status['budget'], target)

    # If budget is extremely low, still bid minimally to avoid wasting remaining life.
    if my_status['budget'] <= 1:
        return my_status['budget']

    # Avoid overbidding when not necessary: cap relative to highest observed aggressive bid.
    if highest_prev_bid > 0:
        bid_cap = max(DAILY_SALARY * 0.95, highest_prev_bid * 0.9)
        bid = min(bid, bid_cap)

    # Final safety clamp
    if bid < 0:
        bid = 0.0
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    dangerous_bids = []
    rich_count = 0
    desperate_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) >= DAILY_SALARY:
                rich_count += 1
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('budget', 0) > 0:
                    dangerous_bids.append(float(bid))

    if not alive_opponents:
        return float(min(budget, 18.0))

    max_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    max_danger = max(dangerous_bids) if dangerous_bids else max_prev

    units = supply / WATER_REQ
    scarcity = units < 2.2
    very_scarce = units < 1.8
    roomy = units >= 2.6

    bid = 0.0

    if hp <= 2 or no_water_days >= 2:
        bid = max(0.92 * DAILY_SALARY, max_danger + 3.0)
    elif hp <= 4 or no_water_days >= 1:
        if very_scarce:
            bid = max(0.82 * DAILY_SALARY, max_danger + 2.0)
        else:
            bid = max(0.68 * DAILY_SALARY, avg_prev + 2.0)
    else:
        if roomy:
            bid = 0.24 * DAILY_SALARY
        elif scarcity:
            if max_danger >= 120:
                bid = 0.34 * DAILY_SALARY
            elif max_danger >= 85:
                bid = 0.48 * DAILY_SALARY
            else:
                bid = max(0.42 * DAILY_SALARY, max_danger + 1.5)
        else:
            if max_danger >= 120:
                bid = 0.30 * DAILY_SALARY
            else:
                bid = max(0.36 * DAILY_SALARY, min(0.58 * DAILY_SALARY, avg_prev * 0.72 + 4.0))

    if rich_count >= 2 and scarcity and hp > 4:
        bid *= 0.9
    if desperate_count >= 2 and hp <= 4:
        bid *= 1.08
    if day >= 8 and hp <= 4:
        bid = max(bid, 0.78 * DAILY_SALARY)
    if day >= 9 and hp > 5 and budget < DAILY_SALARY:
        bid *= 0.85

    min_guard = 6.0 if hp > 4 else 14.0
    bid = max(bid, min_guard)
    bid = min(bid, budget)
    if budget < 12:
        bid = budget

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 

    current_day = day_context['day']
    current_supply = day_context['supply']
    my_hp = my_status['hp']
    my_budget = my_status['budget']
    my_no_water_days = my_status['no_water_days']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if num_alive_opponents == 0:
        return max(1.0, min(my_budget, DAILY_SALARY * 0.1))

    bid = DAILY_SALARY * 0.5

    if my_hp <= 2:
        bid = DAILY_SALARY * 1.2
    elif my_hp <= 4:
        bid = DAILY_SALARY * 0.9
    elif my_no_water_days >= 1:
        bid = DAILY_SALARY * 1.0

    if current_day >= EPISODE_DAYS - 2:
        bid *= 1.15

    total_opponent_water_req = sum(opp['water_requirement'] for opp in alive_opponents)
    total_demand_units = WATER_REQ + total_opponent_water_req

    if total_demand_units > 0 and current_supply < total_demand_units:
        demand_factor = total_demand_units / current_supply
        if demand_factor > 1.5:
            bid *= 1.25
        elif demand_factor > 1.0:
            bid *= 1.1
    elif total_demand_units > 0 and current_supply >= total_demand_units * 1.5:
        bid *= 0.8

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        if highest_prev_bid > DAILY_SALARY * 0.75:
            bid = max(bid, highest_prev_bid + 10)
        elif highest_prev_bid < DAILY_SALARY * 0.4 and current_supply >= total_demand_units * 1.2:
            bid = min(bid, DAILY_SALARY * 0.4)

    min_competitive_bid = DAILY_SALARY * 0.25
    bid = max(min_competitive_bid, bid)

    bid = min(bid, my_budget)

    if my_hp > 5 and my_budget > DAILY_SALARY * 2 and bid > DAILY_SALARY * 1.1:
        bid = min(bid, DAILY_SALARY * 1.1)

    return max(1.0, bid)

